import { describe, it, expect } from "vitest";
import { nextGeneration, type Cell } from "../home/experimenter/experiments/runs/2026-09-05_09-12-26_game-of-life-example-mapping_v6.1.5-pure-split-cc_opus-5-no-thinking/src/game-of-life.js";

// Naive brute-force reference over a bounded window, straight from the spec text.
function reference(cells: Cell[]): Cell[] {
  const live = new Set(cells.map(([x, y]) => `${x},${y}`));
  const out: Cell[] = [];
  const xs = cells.map(([x]) => x), ys = cells.map(([, y]) => y);
  if (cells.length === 0) return [];
  for (let x = Math.min(...xs) - 1; x <= Math.max(...xs) + 1; x++) {
    for (let y = Math.min(...ys) - 1; y <= Math.max(...ys) + 1; y++) {
      let n = 0;
      for (let dx = -1; dx <= 1; dx++)
        for (let dy = -1; dy <= 1; dy++)
          if ((dx || dy) && live.has(`${x + dx},${y + dy}`)) n++;
      const alive = live.has(`${x},${y}`);
      if (alive ? n === 2 || n === 3 : n === 3) out.push([x, y]);
    }
  }
  return out;
}

describe("fuzz vs reference", () => {
  it("matches a naive reference on random boards", () => {
    let seed = 12345;
    const rnd = () => (seed = (seed * 1103515245 + 12345) % 2147483648) / 2147483648;
    for (let iter = 0; iter < 3000; iter++) {
      const n = 1 + Math.floor(rnd() * 9);
      const set = new Set<string>();
      const cells: Cell[] = [];
      for (let i = 0; i < n; i++) {
        const x = Math.floor(rnd() * 11) - 5;
        const y = Math.floor(rnd() * 11) - 5;
        const k = `${x},${y}`;
        if (!set.has(k)) { set.add(k); cells.push([x, y]); }
      }
      const got = new Set(nextGeneration(cells).map(String));
      const want = new Set(reference(cells).map(String));
      expect(got, `board=${JSON.stringify(cells)}`).toEqual(want);
    }
  });
});
EOF
